          :root {
              --primary-color: #8a0303; --secondary-color: #c5b358; --alert-color: #b71c1c;
              --bg-color: #1f1d1b; --border-color: #4e443a; --section-bg: #2b2826; --header-bg: #3a2d2d;
              --text-color: #d1c7b7; --text-muted: #8c8273;
          }
          .grimoire-dashboard {
              font-family: 'EB Garamond', serif; font-size: 14px; color: var(--text-color);
              background-color: var(--bg-color); border: 1px solid var(--border-color); border-radius: 8px;
              padding: 12px; max-width: 620px; box-sizing: border-box; box-shadow: 0 6px 12px rgba(0,0,0,0.4);
              transition: background-color 0.5s, border-color 0.5s;
          }

          /* --- 世界A 主题 (现实学院 - 宁静嫩绿) --- */
          .theme-world-a {
              --primary-color: #2e7d32; --secondary-color: #558b2f; --alert-color: #b71c1c;
              --bg-color: #f0f4f0; --border-color: #a5d6a7; --section-bg: #e8f5e9; --header-bg: #c8e6c9;
              --text-color: #212121; --text-muted: #5f5f5f;
          }

          /* --- 低SAN值 主题 (精神崩溃 - 猩红警报) --- */
          .theme-low-san {
              --primary-color: #d32f2f; --secondary-color: #f5f5f5; --alert-color: #ffcdd2;
              --bg-color: #1a0000; --border-color: #5f0000; --section-bg: #2d0000; --header-bg: #4b0000;
              --text-color: #e0e0e0; --text-muted: #9e9e9e;
          }

          /* --- 通用样式 --- */
          .grimoire-dashboard b { color: var(--secondary-color); font-weight: 700; font-family: 'Cinzel', serif; }
          .grimoire-dashboard .header {
              font-weight: 700; text-align: center; margin-bottom: 12px; border-bottom: 1px solid var(--border-color);
              padding-bottom: 8px; font-size: 16px; color: var(--secondary-color);
              display: flex; flex-wrap: wrap; justify-content: space-around; align-items: center; gap: 5px 15px; font-family: 'Cinzel', serif;
              transition: border-color 0.5s, color 0.5s;
          }
          .grimoire-dashboard .section { margin-bottom: 12px; border-radius: 6px; overflow: hidden; border: 1px solid var(--border-color); transition: border-color 0.5s; }
          .grimoire-dashboard .section-header {
              font-weight: 700; padding: 6px 10px; background-color: var(--header-bg);
              margin-bottom: 0; display: flex; align-items: center; gap: 8px; font-size: 14px; font-family: 'Cinzel', serif;
              transition: background-color 0.5s;
          }
          .grimoire-dashboard .section-content { padding: 10px; background-color: var(--section-bg); transition: background-color 0.5s; }
          .grimoire-dashboard .section-content-alt { padding: 10px; background-color: var(--bg-color); transition: background-color 0.5s; }
          .grimoire-dashboard ul { list-style-type: none; padding-left: 0; margin: 0; }
          .grimoire-dashboard li { margin-bottom: 6px; padding-bottom: 6px; border-bottom: 1px solid var(--border-color); transition: border-color 0.5s; }
          .grimoire-dashboard li:last-child { border-bottom: none; }
          .grimoire-dashboard .sub-text { font-size: 0.9em; color: var(--text-muted); display: block; padding-left: 16px; margin-top: 4px; font-style: italic; transition: color 0.5s; }
          .grimoire-dashboard #db-san.low-san-alert { color: var(--alert-color); animation: pulse 1.5s infinite; }
