                  <b><i class="fas fa-eye"></i> 环境:</b> <span id="db-environment" class="sub-text" style="padding-left:0; margin-top:2px;">--</span>
              </div>
          </div>
          <div class="section">
              <div class="section-header"><span><i class="fas fa-users"></i> 周围人物</span></div>
              <div class="section-content" id="db-characters-content"></div>
          </div>
          <div class="section">
              <div class="section-header"><span><i class="fas fa-heart-crack"></i> 人际关系</span></div>
              <div class="section-content" id="db-relationships-content"></div>
          </div>
          <div class="section">
              <div class="section-header"><span><i class="fas fa-scroll"></i> 近期事务</span></div>
              <div class="section-content" id="db-quests-content"></div>
          </div>
      </div>
