  <script src="https://cdnjs.cloudflare.com/ajax/libs/lodash.js/4.17.21/lodash.min.js"></script>
  <script>
      $(document).ready(function() {
          function getVal(path, defaultValue = null) {
              const all_vars = typeof getAllVariables === 'function' ? getAllVariables() : {};
              let value = _.get(all_vars, 'stat_data.' + path, defaultValue);
              if (Array.isArray(value) && value.length === 2 && typeof value[1] === 'string' && !_.get(value, '[0].$arrayMeta')) { return value[0]; }
              return (value !== null && value !== undefined) ? value : defaultValue;
          }

          function populateDashboard() {
              if ($('#status-block-wrapper').length === 0) return;

              const currentWorld = getVal('世界状态.当前世界');
              const sanValue = parseInt(getVal('世界状态.SAN值', 100));
              const characters = getVal('角色档案', {});
              const dashboard = $('.grimoire-dashboard');

              // **动态主题切换逻辑**
              dashboard.removeClass('theme-world-a theme-low-san');
              $('#db-san').removeClass('low-san-alert');

              if (sanValue < 30) {
                  dashboard.addClass('theme-low-san');
                  $('#db-san').addClass('low-san-alert');
              } else if (currentWorld === 'A') {
                  dashboard.addClass('theme-world-a');
              }
              // 默认 (World B, SAN >= 30) 不需要添加任何类

              // Header
              $('#db-world').html(currentWorld === 'A' ? '<i class="fas fa-school"></i> <b>现实</b>' : '<i class="fas fa-dungeon"></i> <b>异界</b>');
              $('#db-time').text(getVal('世界状态.时间') || '--');
              $('#db-weather').text(getVal('世界状态.天气') || '--');
              $('#db-san').text(sanValue || '--');

              // Scene Info
              $('#db-location').text(getVal('世界状态.地点') || '--');
              $('#db-environment').text(getVal('世界状态.环境') || '--');

              // Characters (Filtered by current world, user excluded)
              let charactersHtml = '<ul>';
              let characterCount = 0;
              for (const name in characters) {
                  const characterWorld = getVal(`角色档案.${name}.所在世界`);
                  if (Object.hasOwnProperty.call(characters, name) && name !== 'user' && characterWorld && characterWorld.includes(currentWorld)) {
                      charactersHtml += `<li><b>${name}:</b><span class="sub-text"><b>姿态:</b> ${getVal(`角色档案.${name}.姿态`)}</span><span class="sub-text"><b>行动:</b> ${getVal(`角色档案.${name}.当前行动`)}</span></li>`;
                      characterCount++;
                  }
              }
              if (characterCount === 0) { charactersHtml += '<li>当前无其他人物在场</li>'; }
              $('#db-characters-content').html(charactersHtml + '</ul>');

              // Relationships (Filtered by current world, user excluded)
              let relationshipsHtml = '<ul>';
              let relationshipCount = 0;
              for (const name in characters) {
                  const characterWorld = getVal(`角色档案.${name}.所在世界`);
                  if (Object.hasOwnProperty.call(characters, name) && name !== 'user' && characterWorld && characterWorld.includes(currentWorld)) {
                      relationshipsHtml += `
                          <li><b>${name}</b><br>
                          <span class="sub-text">好感度: <b>${getVal(`角色档案.${name}.好感度`)}</b> | 欲望: <b>${getVal(`角色档案.${name}.欲望`)}</b> | 关系: <b>${getVal(`角色档案.${name}.关系阶段`)}</b></span>
                          <span class="sub-text"><b>独白:</b> <i>“${getVal(`角色档案.${name}.内心独白`)}”</i></span>
                          <span class="sub-text"><b>预判:</b> ${getVal(`角色档案.${name}.下一步行动`)}</span>
                          </li>`;
                      relationshipCount++;
                  }
              }
              if (relationshipCount === 0) { relationshipsHtml += '<li>暂无人际关系</li>'; }
              $('#db-relationships-content').html(relationshipsHtml + '</ul>');

              // Quests
              const quests = getVal('当前任务', []);
              let questsHtml = '<ul>';
              if (quests && quests.length > 0) {
                  quests.forEach(quest => { questsHtml += `<li><i class="fas fa-book-open"></i> ${quest}</li>`; });
              } else {
                  questsHtml += '<li>暂无明确事务</li>';
              }
              $('#db-quests-content').html(questsHtml + '</ul>');
          }

          populateDashboard();
          if (typeof TavernHelper !== 'undefined') {
              TavernHelper.on('variablesupdated', populateDashboard);
          }
      });
  </script>
  </body>
  </html>
